import{X as A,l as n,a1 as C,L as M}from"./index.js";import{c as s,M as H,V as U,W as O}from"./ubsYearbook.js";const D={cn:{then:"1900 年",now:"今天",rail:"铁路",shrunk:"纺织 · 钢铁 · 煤炭",rest:"其余",fresh:"科技 · 医疗",under:"＜1%",lead:(e,r)=>`1900 年美国上市公司市值的 ${e}% 待在今天已经萎缩或消失的行业里；今天 ${r}% 的市值来自 1900 年几乎不存在的行业。中间那一百二十六年没有画出来——年鉴只给了两个快照，补一条曲线就是编数据。`,railNote:e=>`铁路一度占到美国市场的 ${e}%，今天不到 1%。但这条粗带缩成一根线，不等于持有它的人输了：自 1900 年以来，铁路跑赢了整个美国市场，也跑赢了取代它的那些新技术。`,claphamNote:"还有一层：今天科技的权重仍然小于 1900 年的铁路——而 1900 年那个数字，已经是铁路自己大洗牌之后的读数。",caution:"只有三个数字有出处：63%、＜1%、80% 与 70%。其余色带只标行业名，宽度是为了让两列各自加到一百，不要当成权重读。",mRail:"铁路 1900 → 今天",mShrunk:"1900 年属于已萎缩行业",mFresh:"今天来自当年不存在的行业",sourceLabel:"来源",alt:"1900 年与今天美国股市行业构成的对照：铁路从 63% 缩到不足 1%，科技与医疗从几乎为零长到 70%。"},tw:{then:"1900 年",now:"今天",rail:"鐵路",shrunk:"紡織 · 鋼鐵 · 煤炭",rest:"其餘",fresh:"科技 · 醫療",under:"＜1%",lead:(e,r)=>`1900 年美國上市公司市值的 ${e}% 待在今天已經萎縮或消失的產業裡；今天 ${r}% 的市值來自 1900 年幾乎不存在的產業。中間那一百二十六年沒有畫出來——年鑑只給了兩個快照，補一條曲線就是編數據。`,railNote:e=>`鐵路一度占到美國市場的 ${e}%，今天不到 1%。但這條粗帶縮成一根線，不等於持有它的人輸了：自 1900 年以來，鐵路跑贏了整個美國市場，也跑贏了取代它的那些新技術。`,claphamNote:"還有一層：今天科技的權重仍然小於 1900 年的鐵路——而 1900 年那個數字，已經是鐵路自己大洗牌之後的讀數。",caution:"只有三個數字有出處：63%、＜1%、80% 與 70%。其餘色帶只標產業名，寬度是為了讓兩列各自加到一百，不要當成權重讀。",mRail:"鐵路 1900 → 今天",mShrunk:"1900 年屬於已萎縮產業",mFresh:"今天來自當年不存在的產業",sourceLabel:"來源",alt:"1900 年與今天美國股市產業構成的對照：鐵路從 63% 縮到不足 1%，科技與醫療從幾乎為零長到 70%。"},en:{then:"1900",now:"Today",rail:"Railways",shrunk:"Textiles · steel · coal",rest:"The rest",fresh:"Tech · health care",under:"< 1%",lead:(e,r)=>`${e}% of the 1900 US market sat in industries that have since shrunk or disappeared. ${r}% of today's market comes from industries that barely existed then. The hundred and twenty-six years in between are not drawn: the yearbook publishes two snapshots and nothing between them, and a curve through that gap would be invented.`,railNote:e=>`Railways were once ${e}% of the American market and are under 1% today. A band thinning to a thread is not the same as a loss for the people who held it: since 1900 railways have beaten the US market as a whole, and beaten the technologies that displaced them.`,claphamNote:"One layer further: technology's weight today is still smaller than railways' weight in 1900 — and that 1900 reading was already taken after the railway shakeout.",caution:"Only three figures here are sourced: 63%, under 1%, and the 80% / 70% pair. Every other band carries a name and no number; its width exists so each column sums to a hundred, and should not be read as a weight.",mRail:"Railways, 1900 → today",mShrunk:"1900 cap in industries since shrunk",mFresh:"Today's cap from industries new since 1900",sourceLabel:"Source",alt:"The composition of the US stock market in 1900 versus today: railways fall from 63% to under 1%, while technology and health care grow from almost nothing to 70%."},ja:{then:"1900 年",now:"現在",rail:"鉄道",shrunk:"繊維・鉄鋼・石炭",rest:"その他",fresh:"テクノロジー・ヘルスケア",under:"＜1%",lead:(e,r)=>`1900 年の米国株式時価総額の ${e}% は、今日では縮小あるいは消滅した業種にあった。現在の時価総額の ${r}% は、当時ほとんど存在しなかった業種から来ている。あいだの百二十六年は描いていない——年鑑が与えるのは二つのスナップショットだけであり、その間を曲線でつなげば、それは作られたデータになる。`,railNote:e=>`鉄道はかつて米国市場の ${e}% を占め、今日では 1% に満たない。だが太い帯が一本の線に細るということは、それを持ち続けた者が負けたという意味ではない。1900 年以降、鉄道は米国市場全体を上回り、鉄道を置き換えた新技術をも上回っている。`,claphamNote:"もう一段ある。今日のテクノロジーのウェイトは、1900 年の鉄道のウェイトにいまだ届かない——しかもその 1900 年の数字は、鉄道自身の淘汰が済んだあとの読み値である。",caution:"出所のある数字は三つだけ——63%、1% 未満、そして 80% と 70%。ほかの帯は業種名のみで、幅は各列を百に合わせるためのものであり、ウェイトとして読んではならない。",mRail:"鉄道 1900 →現在",mShrunk:"1900 年に縮小業種が占めた割合",mFresh:"当時なかった業種が占める現在の割合",sourceLabel:"出所",alt:"1900 年と現在の米国株式市場の業種構成の対比：鉄道は 63% から 1% 未満へ、テクノロジーとヘルスケアはほぼゼロから 70% へ。"},es:{then:"1900",now:"Hoy",rail:"Ferrocarriles",shrunk:"Textil · acero · carbón",rest:"El resto",fresh:"Tecnología · salud",under:"< 1%",lead:(e,r)=>`El ${e}% del mercado estadounidense de 1900 estaba en industrias que desde entonces se han encogido o han desaparecido. El ${r}% del mercado de hoy procede de industrias que apenas existían entonces. Los ciento veintiséis años intermedios no se dibujan: el anuario publica dos instantáneas y nada entre ellas, y una curva sobre ese hueco sería inventada.`,railNote:e=>`Los ferrocarriles llegaron a ser el ${e}% del mercado americano y hoy no alcanzan el 1%. Que una banda se adelgace hasta quedar en un hilo no significa que quien la mantuvo perdiera: desde 1900 los ferrocarriles han batido al conjunto del mercado estadounidense, y también a las tecnologías que los desplazaron.`,claphamNote:"Una capa más: el peso de la tecnología hoy sigue siendo menor que el de los ferrocarriles en 1900 — y aquella lectura de 1900 ya se tomó después de la criba del sector ferroviario.",caution:"Solo tres cifras aquí tienen fuente: el 63%, el «menos del 1%» y el par 80% / 70%. Las demás bandas llevan nombre y ningún número; su anchura existe para que cada columna sume cien y no debe leerse como un peso.",mRail:"Ferrocarriles, 1900 → hoy",mShrunk:"Capitalización de 1900 en industrias hoy encogidas",mFresh:"Capitalización de hoy en industrias nuevas desde 1900",sourceLabel:"Fuente",alt:"Composición del mercado bursátil estadounidense en 1900 frente a hoy: los ferrocarriles caen del 63% a menos del 1%, mientras la tecnología y la salud crecen desde casi nada hasta el 70%."},ko:{then:"1900년",now:"오늘",rail:"철도",shrunk:"섬유 · 철강 · 석탄",rest:"나머지",fresh:"기술 · 헬스케어",under:"＜1%",lead:(e,r)=>`1900년 미국 시장 시가총액의 ${e}%는 그 뒤 쪼그라들었거나 사라진 산업에 있었다. 오늘 시가총액의 ${r}%는 당시 거의 존재하지 않던 산업에서 나온다. 그 사이의 126년은 그리지 않았다. 연감이 주는 것은 두 장의 스냅숏뿐이며, 그 틈을 곡선으로 이으면 그것은 지어낸 데이터다.`,railNote:e=>`철도는 한때 미국 시장의 ${e}%였고 오늘은 1%에 미치지 못한다. 그러나 굵은 띠가 한 가닥 실로 가늘어졌다는 것이 그것을 들고 있던 사람이 졌다는 뜻은 아니다. 1900년 이래 철도는 미국 시장 전체를 이겼고, 자신을 대체한 신기술마저 이겼다.`,claphamNote:"한 겹 더 있다. 오늘 기술의 비중은 1900년 철도의 비중에 아직 못 미친다 — 게다가 그 1900년 수치는 철도 자체의 대규모 정리가 끝난 뒤에 읽은 값이다.",caution:"출처가 있는 숫자는 셋뿐이다 — 63%, 1% 미만, 그리고 80% / 70%. 나머지 띠는 산업 이름만 달고 있으며, 그 폭은 각 열의 합을 100으로 맞추기 위한 것이지 비중으로 읽어서는 안 된다.",mRail:"철도, 1900 → 오늘",mShrunk:"1900년, 지금은 쪼그라든 산업의 몫",mFresh:"오늘, 1900년엔 없던 산업의 몫",sourceLabel:"출처",alt:"1900년과 오늘의 미국 주식시장 산업 구성 대비: 철도는 63%에서 1% 미만으로, 기술과 헬스케어는 거의 0에서 70%로."},fr:{then:"1900",now:"Aujourd'hui",rail:"Chemins de fer",shrunk:"Textile · acier · charbon",rest:"Le reste",fresh:"Tech · santé",under:"< 1 %",lead:(e,r)=>`${e} % du marché américain de 1900 se trouvait dans des industries qui ont depuis rétréci ou disparu. ${r} % du marché d'aujourd'hui vient d'industries qui n'existaient pratiquement pas alors. Les cent vingt-six années intermédiaires ne sont pas tracées : l'annuaire publie deux instantanés et rien entre les deux, et une courbe sur cet intervalle serait inventée.`,railNote:e=>`Les chemins de fer ont représenté jusqu'à ${e} % du marché américain ; ils en font moins de 1 % aujourd'hui. Qu'une bande s'amincisse jusqu'au fil ne veut pas dire que celui qui la détenait a perdu : depuis 1900, le rail a battu l'ensemble du marché américain, et aussi les technologies qui l'ont remplacé.`,claphamNote:"Une couche de plus : le poids de la technologie aujourd'hui reste inférieur à celui du rail en 1900 — et ce relevé de 1900 avait déjà été pris après la grande sélection du secteur ferroviaire.",caution:"Trois chiffres seulement sont sourcés ici : 63 %, « moins de 1 % », et le couple 80 % / 70 %. Les autres bandes portent un nom et aucun nombre ; leur largeur existe pour que chaque colonne fasse cent et ne doit pas se lire comme une pondération.",mRail:"Rail, 1900 → aujourd'hui",mShrunk:"Capitalisation de 1900 en industries depuis rétrécies",mFresh:"Capitalisation d'aujourd'hui en industries nées depuis 1900",sourceLabel:"Source",alt:"Composition du marché actions américain en 1900 face à aujourd'hui : le rail passe de 63 % à moins de 1 %, tandis que la technologie et la santé montent de presque rien à 70 %."},de:{then:"1900",now:"Heute",rail:"Eisenbahnen",shrunk:"Textil · Stahl · Kohle",rest:"Der Rest",fresh:"Technik · Gesundheit",under:"< 1 %",lead:(e,r)=>`${e} % des amerikanischen Marktes von 1900 lagen in Branchen, die seither geschrumpft oder verschwunden sind. ${r} % des heutigen Marktes stammen aus Branchen, die es damals kaum gab. Die hundertsechsundzwanzig Jahre dazwischen sind nicht gezeichnet: Das Jahrbuch veröffentlicht zwei Momentaufnahmen und nichts dazwischen, und eine Kurve über diese Lücke wäre erfunden.`,railNote:e=>`Eisenbahnen machten einst ${e} % des amerikanischen Marktes aus, heute unter 1 %. Dass ein Band zum Faden dünn wird, heißt nicht, dass verloren hat, wer es hielt: Seit 1900 hat die Eisenbahn den gesamten US-Markt geschlagen — und auch die Technologien, die sie verdrängt haben.`,claphamNote:"Eine Schicht weiter: Das Gewicht der Technologie ist heute noch immer kleiner als das der Eisenbahnen im Jahr 1900 — und jener Wert von 1900 war bereits nach der Bereinigung der Bahnbranche abgelesen.",caution:"Nur drei Zahlen sind hier belegt: 63 %, „unter 1 %“ sowie das Paar 80 % / 70 %. Alle anderen Bänder tragen einen Namen und keine Zahl; ihre Breite sorgt dafür, dass jede Spalte hundert ergibt, und ist nicht als Gewicht zu lesen.",mRail:"Eisenbahnen, 1900 → heute",mShrunk:"Kapitalisierung 1900 in seither geschrumpften Branchen",mFresh:"Heutige Kapitalisierung in seit 1900 neuen Branchen",sourceLabel:"Quelle",alt:"Zusammensetzung des US-Aktienmarktes 1900 gegenüber heute: Eisenbahnen fallen von 63 % auf unter 1 %, Technologie und Gesundheit wachsen von fast nichts auf 70 %."}},G=820,K=430,m=48,d=3.4,u=m+100*d,Z=156,i=200,l=596,J=640;function b(e,r,p,y){const a=(l-i)*.45;return[`M ${i},${e}`,`C ${i+a},${e} ${l-a},${p} ${l},${p}`,`L ${l},${y}`,`C ${l-a},${y} ${i+a},${r} ${i},${r}`,"Z"].join(" ")}const c={rail:"var(--oxblood)",fresh:"var(--verdant)",mute:"var(--ink-mute)"},k={rail:.34,fresh:.3,mute:.12};function X({kicker:e,title:r,subtitle:p}){const{locale:y}=A(),a=D[y],w=H(),R=O(),S=U(),v=m,h=v+s.railways1900Pct*d,f=h+w*d,x=m,o=x+s.railwaysNowPctMax*d,F=S*(w/(w+R)),T=o+F*d,g=o+S*d,P=[{key:"rail",y0:v,y1:h,name:a.rail,value:`${s.railways1900Pct}%`,tone:"rail"},{key:"shrunk",y0:h,y1:f,name:a.shrunk,tone:"mute"},{key:"rest",y0:f,y1:u,name:a.rest,tone:"mute"}],B=[{key:"rail",y0:x,y1:o,name:a.rail,value:a.under,tone:"rail"},{key:"rest",y0:o,y1:g,name:a.rest,tone:"mute"},{key:"fresh",y0:g,y1:u,name:a.fresh,value:`${s.newNowPct}%`,tone:"fresh"}];return n.jsxs(C,{id:"panel-sector-shift",kicker:e,title:r,subtitle:p,children:[n.jsx("div",{className:"panel-figure sector-slope-wrap",children:n.jsxs("svg",{className:"sector-slope",viewBox:`0 0 ${G} ${K}`,role:"img","aria-label":a.alt,children:[n.jsxs("g",{className:"sector-slope-ribbons",children:[n.jsx("path",{d:b(h,f,o,T),fill:c.mute,fillOpacity:k.mute}),n.jsx("path",{d:b(f,u,T,g),fill:c.mute,fillOpacity:k.mute}),n.jsx("path",{d:b(v,h,x,o),fill:c.rail,fillOpacity:k.rail}),n.jsx("path",{d:b(u,u,g,u),fill:c.fresh,fillOpacity:k.fresh})]}),n.jsx("text",{className:"sector-slope-year",x:i,y:m-16,textAnchor:"end",children:a.then}),n.jsx("text",{className:"sector-slope-year",x:l,y:m-16,textAnchor:"start",children:a.now}),[["l",P,Z,i],["r",B,l,J]].map(([$,E,j,q])=>n.jsx("g",{children:E.map(t=>{const N=(t.y0+t.y1)/2,z=$==="l"?"end":"start",L=$==="l"?j-12:q+12;return n.jsxs("g",{children:[n.jsx("rect",{x:j,y:t.y0,width:q-j,height:Math.max(1.5,t.y1-t.y0),fill:c[t.tone],fillOpacity:t.tone==="mute"?.28:.72}),n.jsx("text",{className:"sector-slope-name",x:L,y:t.value?N-2:N+4,textAnchor:z,children:t.name}),t.value?n.jsx("text",{className:"sector-slope-value num",x:L,y:N+15,textAnchor:z,children:t.value}):null]},t.key)})},$))]})}),n.jsx(M,{items:[{label:a.mRail,value:`${s.railways1900Pct}% → ${a.under}`,tone:"oxblood"},{label:a.mShrunk,value:`${s.shrunk1900Pct}%`},{label:a.mFresh,value:`${s.newNowPct}%`,tone:"verdant"}]}),n.jsx("div",{style:{fontSize:12,color:"var(--ink-soft)",marginTop:12,lineHeight:1.7},children:a.lead(s.shrunk1900Pct,s.newNowPct)}),n.jsx("div",{style:{fontSize:12,color:"var(--ink-soft)",marginTop:8,lineHeight:1.7},children:a.railNote(s.railways1900Pct)}),n.jsx("div",{style:{fontSize:12,color:"var(--ink-soft)",marginTop:8,lineHeight:1.7},children:a.claphamNote}),n.jsx("div",{style:{fontSize:11,color:"var(--ink-faint)",marginTop:10,lineHeight:1.6},children:a.caution}),n.jsxs("div",{style:{fontSize:11,color:"var(--ink-faint)",marginTop:8,lineHeight:1.6},children:[n.jsx("span",{style:{letterSpacing:"0.12em",textTransform:"uppercase",color:"var(--ink-mute)"},children:a.sourceLabel})," · ","UBS Global Investment Returns Yearbook 2026 · ",s.source.cite," · [",s.source.grade,"] ·"," ",s.claphamNote.cite," [",s.claphamNote.grade,"]"]})]})}export{X as PanelSectorShift};
